import{_ as t,o as a,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Importer des modèles et gérer les profils","description":"","frontmatter":{"title":"Importer des modèles et gérer les profils","docId":"user.automations.templates","translationKey":"user.automations.templates","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e9847c93a8a75fd5a58cd115b49b8e0bcb091ceda1dbdf2c226b52667eb17e23","translationRevision":"a3bd159033aeb74889a6f66601928ca79f91621d843c5c82165f22e6c7c0e3a0","order":50},"headers":[],"relativePath":"fr/user/automations/templates.md","filePath":"fr/user/automations/templates.md","lastUpdated":1794611623000}'),o={name:"fr/user/automations/templates.md"};function r(n,e,l,u,d,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="import-templates-and-manage-profiles" tabindex="-1">Importer des modèles et gérer les profils <a class="header-anchor" href="#import-templates-and-manage-profiles" aria-label="Permalink to &quot;Importer des modèles et gérer les profils {#import-templates-and-manage-profiles}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Réutiliser une règle ou un ensemble de règles examinées sans activer d’effets accidentellement. Il faut <strong>Automations</strong>, un fichier JSON ou une entrée de catalogue de confiance, ainsi que les plugins requis par ses actions. Exportez le profil actuel avant de remplacer une configuration établie.</p><h2 id="choose-the-right-surface" tabindex="-1">Choisir le bon outil <a class="header-anchor" href="#choose-the-right-surface" aria-label="Permalink to &quot;Choisir le bon outil {#choose-the-right-surface}&quot;">​</a></h2><p>Un document <code>.tiktemplate.json</code> décrit un événement et ses actions. Un document <code>.tikprofile.json</code> regroupe plusieurs modèles. Ouvrez la boîte de dialogue des modèles depuis Automations pour les modèles intégrés/personnalisés, sa bibliothèque Cloud ou l’importation manuelle de modèles. Utilisez la barre d’outils des profils pour leur création, sélection, exportation et importation manuelle. <strong>Plugins → Explore</strong> parcourt les plugins ; les modèles et profils se trouvent ici.</p><h2 id="review-and-import" tabindex="-1">Examiner et importer <a class="header-anchor" href="#review-and-import" aria-label="Permalink to &quot;Examiner et importer {#review-and-import}&quot;">​</a></h2><ol><li>Ouvrez la boîte de dialogue d’importation voulue et choisissez un fichier ou collez du JSON pris en charge. Vérifiez le nom préparé et la source avant de poursuivre.</li><li>Pour un modèle, examinez le déclencheur, les types d’action et les paramètres. Pour un profil, examinez aussi le nombre d’entrées et les paramètres communs.</li><li>Remplacez les destinations d’exemple, chemins de médias et identifiants de spectateurs par des valeurs adaptées à votre configuration. Ne collez pas d’identifiants secrets dans un fichier destiné au partage.</li><li>Appliquez/importez explicitement et attendez le résultat. Ne supposez pas les définitions désactivées : examinez les valeurs enabled. Sélectionnez-les ensuite et examinez chaque action et événement avant d’activer explicitement ceux souhaités.</li><li>Commencez par un test limité au journal ou examinez d’abord les définitions. Les tests HTTP, audio, points ou plugins peuvent exécuter des effets.</li><li>Avant de confirmer un profil, examinez l’activation de ses membres et la désactivation des autres, y compris éléments isolés et membres précédemment désactivés. Les effets exigent déclencheurs/conditions ; ce n’est pas un sync Cloud.</li></ol><p>Les paramètres tels que <code>{{ params.giftName }}</code> sont résolus lors de l’application du modèle. Les références d’exécution telles que <code>{{ event.user.uniqueId }}</code> restent présentes pour chaque événement, tandis que les <a href="./variables.html">variables globales</a> fournissent des valeurs enregistrées partagées lors de l’exécution.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les outils locaux d’importation et d’exportation des modèles/profils sont disponibles. Parcourir Cloud nécessite la capacité correspondante de l’hôte ainsi que le compte/service. Un aperçu de catalogue ne prouve pas que le service externe d’une action fonctionne. Des plugins manquants peuvent rendre les définitions importées inutilisables jusqu’à leur installation et configuration.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Pour du JSON invalide, utilisez les erreurs d’analyse indiquées et le type de document attendu ; renommer un fichier JSON quelconque ne le convertit pas. En cas de conflit de révision, actualisez la bibliothèque enregistrée avant de réappliquer. Conservez le profil fonctionnel exporté et consultez les <a href="./../preferences/backups.html">sauvegardes</a> pour les données que l’exportation de profil n’inclut pas.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>L’import manuel de modèle enregistre d’abord un document de catalogue ; son application crée actions/événements liés. Le parseur utilise true si <code>enabled</code> manque et l’application conserve ces valeurs. L’import manuel de profil prépare ses entrées pour revue propriétaire. Le catalogue Cloud stocke des modèles ; un profil Cloud prépare une mutation avec provenance. Ni origine ni aperçu réussi ne garantissent une désactivation universelle. Examinez comparaison finale et états enregistrés. En CLI, utilisez explicitement <code>tiktools template import file.tiktemplate.json --disabled</code> ou <code>tiktools template profile-import file.tikprofile.json --disabled</code>.</p><p>Changer de profil modifie l’activation : la confirmation active les membres du profil cible et désactive toutes les actions/événements hors profil, y compris les éléments isolés. Des membres précédemment désactivés peuvent être activés. Vérifiez les deux listes. Les effets exigent encore déclencheur, conditions et runtime ; le changement n’envoie pas de synchronisation Cloud à lui seul.</p>',15)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
